(async()=>{let id; await run(async c=>{const tools=(await c.listTools()).tools; for(const n of ['remember','recall','forget']) assert(tools.some(t=>t.name===n),'Missing '+n);const before=result(await c.callTool({name:'recall',arguments:{entity:'gbrain-install-check'}}));assert(JSON.stringify(before).includes('quartz lantern 7600'),'Did not recall CLI marker '+JSON.stringify(before));console.log('Registered MCP recalled CLI fact #1');const r=result(await c.callTool({name:'remember',arguments:{fact:label,entity:'gbrain-mcp-install-check',provenance:'install-check',content_origin:'inferred',ttl:'12h'}}));id=r.id??r.outcome?.id;assert(id&&r.state!=='pending','MCP write not committed: '+JSON.stringify(r));console.log('Registered MCP remembered fact #'+id);}); await run(async c=>{const r=result(await c.callTool({name:'recall',arguments:{entity:'gbrain-mcp-install-check'}}));assert(r.facts?.some(f=>String(f.id)===String(id)&&f.fact===label),'Reopened MCP recall missed marker: '+JSON.stringify(r));console.log('Fresh MCP process recalled fact #'+id+' with exact text'); const params=(await c.listTools()).tools.find(t=>t.name==='forget').inputSchema;const k=params.properties.fact_id?'fact_id':'id'; const args={[k]:params.properties[k]?.type==='number'?Number(id):String(id),reason:'Synthetic installation check complete'}; result(await c.callTool({name:'forget',arguments:args}));const after=result(await c.callTool({name:'recall',arguments:{entity:'gbrain-mcp-install-check'}}));assert(!after.facts?.some(f=>String(f.id)===String(id)),'Fact still active');console.log('MCP test fact withdrawn and verified absent from active recall');});})().catch(e=>{console.error(e);process.exitCode=1;});
